mapper.select:
SELECT DATE_FORMAT(SAVE_TIME, '%Y-%m-%d') AS dtStats, MSG_TYPE AS serviceType, COUNT(*) AS inCnt, SUM(CASE WHEN RESULT = '0' OR RESULT = '1000' THEN 1 ELSE 0 END) AS succCnt, SUM(CASE WHEN RESULT IN ('9999', '-1') THEN 1 ELSE 0 END) AS errorCnt, SUM(CASE WHEN RESULT NOT IN ('0', '1000', '9999', '-1', '') AND RESULT IS NOT NULL THEN 1 ELSE 0 END) AS failCnt, SUM(CASE WHEN RESULT = '' OR RESULT IS NULL THEN 1 ELSE 0 END) AS waitCnt, 0 AS ingCnt FROM ${tableName} WHERE 1=1
AND EXT_COL3 = #{userId}
AND MSG_TYPE = #{serviceType}
AND SAVE_TIME >= #{startDate}
AND SAVE_TIME <= #{endDate}
GROUP BY DATE_FORMAT(SAVE_TIME, '%Y-%m-%d'), MSG_TYPE ORDER BY dtStats DESC, serviceType

SELECT EXT_COL3 AS userId, MSG_TYPE AS serviceType, COUNT(*) AS totalCnt, SUM(CASE WHEN RESULT = '0' OR RESULT = '1000' THEN 1 ELSE 0 END) AS succCnt, SUM(CASE WHEN RESULT NOT IN ('0', '1000') OR RESULT IS NULL THEN 1 ELSE 0 END) AS failCnt FROM ${tableName} WHERE 1=1
AND EXT_COL3 IN
#{userId}
AND SAVE_TIME >= #{startDate}
AND SAVE_TIME <= #{endDate}
GROUP BY EXT_COL3, MSG_TYPE ORDER BY EXT_COL3, MSG_TYPE

SELECT CASE WHEN ext_col0 IS NULL THEN '문자메시지' ELSE '설문조사' END AS serviceTypeName, CASE WHEN ext_col0 IS NULL THEN CASE MSG_TYPE WHEN 'S' THEN 'SMS' WHEN 'L' THEN 'LMS' ELSE 'MMS' END ELSE '설문' END AS category, COUNT(*) AS count, NULL AS unitPrice, NULL AS amount, '' AS remarks FROM ${tableName} WHERE RESULT IN ('0', '1000')
AND EXT_COL3 = #{userId}
AND SAVE_TIME >= #{startDate}
AND SAVE_TIME <= #{endDate}
GROUP BY serviceTypeName, category

SELECT
    COUNT(*) AS totalCnt,
    SUM(CASE WHEN RESULT = '0' OR RESULT = '1000' THEN 1 ELSE 0 END) AS succCnt,
    SUM(CASE WHEN RESULT NOT IN ('0', '1000') OR RESULT IS NULL THEN 1 ELSE 0 END) AS failCnt
FROM ${tableName}


        EXT_COL3 = #{userId}
